package com.youngone.mediacontrol.policy.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="policy_deployments")public class PolicyDeployment{
 @Id private UUID id;@Column(name="policy_id",nullable=false)private UUID policyId;@Column(name="previous_policy_id")private UUID previousPolicyId;@Column(name="rollout_percentage",nullable=false)private int rolloutPercentage;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private DeploymentStatus status;@Column(name="started_by",nullable=false,length=100)private String startedBy;@Column(name="started_at",nullable=false)private Instant startedAt;@Column(name="ended_at")private Instant endedAt;
 protected PolicyDeployment(){}public PolicyDeployment(UUID id,UUID policyId,UUID previous,int percentage,String actor,Instant now){this.id=id;this.policyId=policyId;this.previousPolicyId=previous;this.rolloutPercentage=percentage;this.status=percentage==100?DeploymentStatus.COMPLETED:DeploymentStatus.RUNNING;this.startedBy=actor;this.startedAt=now;}public boolean includes(UUID agentId){return Math.floorMod(agentId.hashCode(),100)<rolloutPercentage;}public void rollback(){status=DeploymentStatus.ROLLED_BACK;endedAt=Instant.now();}public UUID getId(){return id;}public UUID getPolicyId(){return policyId;}public UUID getPreviousPolicyId(){return previousPolicyId;}public int getRolloutPercentage(){return rolloutPercentage;}public DeploymentStatus getStatus(){return status;}
}
